-- Downtime остаётся в ledger и проходит исходные ограничения интервала. Дата конца учитывает исключённую последнюю микросекунду без потери точности на полуночи.
WITH p AS (SELECT try(json_parse(payload)) AS j FROM {{target:oil_stg__v_event_parsed}} WHERE event_type='downtime'), v AS (SELECT json_extract_scalar(j,'$.well_id') AS well_id,json_extract_scalar(j,'$.reason') AS reason,json_extract_scalar(j,'$.start_at') AS start_text,json_extract_scalar(j,'$.end_at') AS end_text,try(from_iso8601_timestamp_nanos(json_extract_scalar(j,'$.start_at'))) AS start_at,try(from_iso8601_timestamp_nanos(json_extract_scalar(j,'$.end_at'))) AS end_at FROM p), u AS (SELECT v.*,at_timezone(start_at,'UTC') AS start_utc,at_timezone(end_at,'UTC') AS end_utc FROM v) SELECT count(*) AS n FROM u WHERE well_id IS NULL OR NOT regexp_like(well_id,'^[A-Za-z0-9_-]+$') OR reason IS NULL OR reason NOT IN ('EQUIPMENT','POWER','PLANNED') OR start_at IS NULL OR end_at IS NULL OR NOT coalesce(regexp_like(start_text,'[Tt].*([Zz]|[+-][0-9]{2}:[0-9]{2})$'),false) OR NOT coalesce(regexp_like(end_text,'[Tt].*([Zz]|[+-][0-9]{2}:[0-9]{2})$'),false) OR start_at IS DISTINCT FROM try_cast(start_at AS timestamp(6) with time zone) OR end_at IS DISTINCT FROM try_cast(end_at AS timestamp(6) with time zone) OR end_at<=start_at OR cast(start_utc AS date) IS DISTINCT FROM (CASE WHEN end_utc=date_trunc('day',end_utc) THEN date_add('day',-1,cast(end_utc AS date)) ELSE cast(end_utc AS date) END);
